/* 아이디어 등록 idea.insertIdea */
INSERT INTO TB_IDEA (
    IDEA_ID
    , IDEA_TYPE_CD
    , AGENT_ID
    , TITLE
    , CONTENT
    , STATUS_CD
    , LIKE_CNT
    , USE_YN
    , CREATE_DT
    , CREATE_ID
) VALUES (
    #{ideaId}
    , #{ideaTypeCd}
    , NULLIF(#{agentId}, '')
    , #{title}
    , #{content}
    , #{statusCd}
    , 0
    , 'Y'
    , NOW()
    , #{createId}
)

mapper.update:
/* 아이디어 수정 (본인 글 + 코멘트 전만 — 조건은 ServiceImpl에서 확인) idea.updateIdea */
UPDATE TB_IDEA
SET
    IDEA_TYPE_CD = #{ideaTypeCd}
    , AGENT_ID = NULLIF(#{agentId}, '')
    , TITLE = #{title}
    , CONTENT = #{content}
    , MODIFY_DT = NOW()
    , MODIFY_ID = #{modifyId}
WHERE IDEA_ID = #{ideaId}
    AND USE_YN = 'Y'

/* 아이디어 삭제 — 논리 삭제(USE_YN = 'N'), 데이터·첨부·추천은 그대로 보관 idea.deleteIdea */
UPDATE TB_IDEA
SET
    USE_YN = 'N'
    , MODIFY_DT = NOW()
    , MODIFY_ID = #{modifyId}
WHERE IDEA_ID = #{ideaId}
    AND USE_YN = 'Y'

