    IDEA_FILE_ID
    , IDEA_ID
    , FILE_PATH
    , FILE_NM
    , FILE_SIZE
    , FILE_TYPE
    , CREATE_DT
    , CREATE_ID
) VALUES (
    #{ideaFileId}
    , #{ideaId}
    , #{filePath}
    , #{fileNm}
    , #{fileSize}
    , #{fileType}
    , NOW()
    , #{createId}
)

