/* 추천수 재계산 (TB_IDEA_LIKE 합계) idea.updateIdeaLikeCnt */
UPDATE TB_IDEA
SET LIKE_CNT = (SELECT COUNT(1) FROM tb_idea_like WHERE IDEA_ID = #{ideaId} AND ANSR_ID = '')
WHERE IDEA_ID = #{ideaId}
